const elMunicipio = document.getElementById('f-municipio');
const elDepartamento = document.getElementById('f-departamento');
const elOpcionesMunicipio = document.getElementById('opciones-municipio');
const elOpcionesDepartamento = document.getElementById('opciones-departamento');
const elInstalado = document.getElementById('f-instalado');
const elDocumental = document.getElementById('f-documental');
const elBuscar = document.getElementById('f-buscar');
const elOpcionesTipo = document.getElementById('opciones-tipo');
const elAlternarTipos = document.getElementById('btn-tipos');
const elTbody = document.getElementById('tbody');
const elConteo = document.getElementById('conteo');
const elPanelPendientes = document.getElementById('panel-pendientes');
const elListadoPendientes = document.getElementById('listado-pendientes');
const elEmpty = document.getElementById('empty-state');
const elTableToolbar = document.querySelector('.table-toolbar');
const elTableScroll = document.querySelector('.table-scroll');
const elTable = elTableScroll.querySelector('table');
const elStickyTableHead = document.getElementById('sticky-table-head');
const stickyHeaderTable = elTable.cloneNode(false);
stickyHeaderTable.appendChild(elTable.querySelector('thead').cloneNode(true));
elStickyTableHead.appendChild(stickyHeaderTable);

let stickyHeadUpdatePending = false;
function updateStickyTableHead() {
  if (window.matchMedia('(max-width: 640px)').matches) {
    elStickyTableHead.classList.remove('is-visible');
    return;
  }
  const toolbarRect = elTableToolbar.getBoundingClientRect();
  const scrollRect = elTableScroll.getBoundingClientRect();
  const headerHeight = elTable.querySelector('thead').getBoundingClientRect().height;
  const shouldShow = scrollRect.top < toolbarRect.bottom
    && scrollRect.bottom > toolbarRect.bottom + headerHeight;

  elStickyTableHead.classList.toggle('is-visible', shouldShow);
  if (!shouldShow) return;

  const borderLeft = parseFloat(getComputedStyle(elTableScroll).borderLeftWidth) || 0;
  elStickyTableHead.style.top = `${toolbarRect.bottom}px`;
  elStickyTableHead.style.left = `${scrollRect.left + borderLeft}px`;
  elStickyTableHead.style.width = `${elTableScroll.clientWidth}px`;
  elStickyTableHead.style.height = `${headerHeight}px`;
  stickyHeaderTable.style.width = `${elTable.offsetWidth}px`;
  stickyHeaderTable.style.transform = `translateX(-${elTableScroll.scrollLeft}px)`;
}

function scheduleStickyTableHeadUpdate() {
  if (stickyHeadUpdatePending) return;
  stickyHeadUpdatePending = true;
  requestAnimationFrame(() => {
    updateStickyTableHead();
    stickyHeadUpdatePending = false;
  });
}

window.addEventListener('scroll', scheduleStickyTableHeadUpdate, {passive: true});
window.addEventListener('resize', scheduleStickyTableHeadUpdate);
elTableScroll.addEventListener('scroll', scheduleStickyTableHeadUpdate, {passive: true});

const sitiosInstalados = new Set(DATA.filter(r => r.instalado).map(r => r.fila_excel));
const documentosCargados = DATA.reduce((total, r) => (
  total + (r.instalado && r.estado === 'con_soporte' ? r.archivos.length : 0)
), 0);
document.getElementById('resumen-sitios-instalados').textContent = sitiosInstalados.size;
document.getElementById('resumen-documentos-cargados').textContent = documentosCargados;
 
function unico(campo) {
  return [...new Set(DATA.map(r => r[campo]).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'es'));
}
 
function poblarOpciones(el, valores) {
  el.replaceChildren();
  for (const v of valores) {
    const opt = document.createElement('option');
    opt.value = v;
    el.appendChild(opt);
  }
}

function sitiosSegunEstadoDocumental(estadoDocumental) {
  if (!estadoDocumental) return null;

  const pendientesPorSitio = new Map();
  for (const r of DATA) {
    if (!r.instalado) continue;
    const clave = `${r.municipio}||${r.departamento}`;
    if (!pendientesPorSitio.has(clave)) pendientesPorSitio.set(clave, false);
    if (r.estado === 'pendiente' || r.estado === 'sin_dato') {
      pendientesPorSitio.set(clave, true);
    }
  }

  return new Set([...pendientesPorSitio]
    .filter(([, tienePendientes]) => estadoDocumental === 'en_proceso' ? tienePendientes : !tienePendientes)
    .map(([clave]) => clave));
}

function opcionesSegunFiltros(campo) {
  const estado = elInstalado.value;
  const sitiosDocumentales = sitiosSegunEstadoDocumental(elDocumental.value);
  const municipioActual = elMunicipio.value.trim().toLocaleLowerCase('es');
  const departamentoActual = elDepartamento.value.trim().toLocaleLowerCase('es');

  const filas = DATA.filter(r => {
    if (estado === 'instalado' && !r.instalado) return false;
    if (estado === 'no_instalado' && r.instalado) return false;
    if (sitiosDocumentales && !sitiosDocumentales.has(`${r.municipio}||${r.departamento}`)) return false;
    if (campo !== 'municipio' && municipioActual && !r.municipio.toLocaleLowerCase('es').includes(municipioActual)) return false;
    if (campo !== 'departamento' && departamentoActual && !r.departamento.toLocaleLowerCase('es').includes(departamentoActual)) return false;
    return true;
  });

  return [...new Set(filas.map(r => r[campo]).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'es'));
}

function syncSelects() {
  poblarOpciones(elOpcionesMunicipio, opcionesSegunFiltros('municipio'));
  poblarOpciones(elOpcionesDepartamento, opcionesSegunFiltros('departamento'));
}

syncSelects();
const tiposDocumentales = unico('tipo');
let indiceTipoActivo = -1;

function cerrarOpcionesTipo() {
  elOpcionesTipo.hidden = true;
  elBuscar.setAttribute('aria-expanded', 'false');
  elAlternarTipos.setAttribute('aria-expanded', 'false');
  elBuscar.removeAttribute('aria-activedescendant');
  indiceTipoActivo = -1;
}

function actualizarTipoActivo() {
  const opciones = elOpcionesTipo.querySelectorAll('[role="option"]');
  opciones.forEach((opcion, indice) => {
    const activo = indice === indiceTipoActivo;
    opcion.classList.toggle('is-active', activo);
    opcion.setAttribute('aria-selected', String(activo));
  });
  const activa = opciones[indiceTipoActivo];
  if (activa) {
    elBuscar.setAttribute('aria-activedescendant', activa.id);
  } else {
    elBuscar.removeAttribute('aria-activedescendant');
  }
}

function abrirOpcionesTipo() {
  const consulta = elBuscar.value.trim().toLocaleLowerCase('es');
  const coincidencias = tiposDocumentales.filter(tipo => tipo.toLocaleLowerCase('es').includes(consulta));
  elOpcionesTipo.replaceChildren();
  indiceTipoActivo = -1;

  if (coincidencias.length) {
    coincidencias.forEach((tipo, indice) => {
      const opcion = document.createElement('div');
      opcion.id = `opcion-tipo-${indice}`;
      opcion.className = 'search-option';
      opcion.setAttribute('role', 'option');
      opcion.setAttribute('aria-selected', 'false');
      opcion.textContent = tipo;
      opcion.addEventListener('mousedown', evento => evento.preventDefault());
      opcion.addEventListener('click', () => {
        elBuscar.value = tipo;
        cerrarOpcionesTipo();
        limpiarSeleccionPendiente();
        aplicarFiltros();
      });
      elOpcionesTipo.appendChild(opcion);
    });
  } else {
    const vacio = document.createElement('div');
    vacio.className = 'search-empty';
    vacio.textContent = 'Sin tipos coincidentes';
    elOpcionesTipo.appendChild(vacio);
  }

  elOpcionesTipo.hidden = false;
  elBuscar.setAttribute('aria-expanded', 'true');
  elAlternarTipos.setAttribute('aria-expanded', 'true');
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function renderNoRequiere(r) {
  const mensaje = r.archivos[0] || '';
  if (mensaje.toUpperCase().startsWith('INSTALADO POR DECRETO DE CALAMIDAD')) {
    return '<span class="tag-noreq">' + escapeHtml(mensaje) + '</span>';
  }
  if (mensaje.toUpperCase() === 'NO APLICA') {
    return '<span class="tag-noreq">NO APLICA</span>';
  }
  return '<span class="tag-noreq">No requiere</span>';
}
 
function renderRuta(r) {
  if (r.estado === 'no_requiere') return renderNoRequiere(r);
  if (r.estado === 'sin_dato') return '<span class="dash">—</span>';
  if (r.estado === 'pendiente') return '<span class="dash">—</span>';

  const rutaHtml = escapeHtml(r.ruta || '').split('\\').join('\\<wbr>');
  if (r.href) {
    return '<a href="' + escapeHtml(r.href) + '" target="_blank" rel="noopener noreferrer" style="color: var(--accent); text-decoration: underline; word-break: break-word;">' + rutaHtml + '</a>';
  }

  // permite que el navegador corte la ruta después de cada backslash,
  // en vez de partir palabras a la mitad
  return rutaHtml;
}

function renderArchivo(r) {
  if (r.estado === 'pendiente' || r.estado === 'sin_dato') return '<span class="dash">—</span>';
  if (r.estado === 'no_requiere') return renderNoRequiere(r);
  if (r.archivos.length === 1) return escapeHtml(r.archivos[0]);
  return '<ul>' + r.archivos.map(a => '<li>' + escapeHtml(a) + '</li>').join('') + '</ul>';
}

let grupoPendienteActivo = null;

function renderBadgeGrupo(rows, grupoKey) {
  const pendientes = rows.filter(r => r.estado === 'pendiente' || r.estado === 'sin_dato').length;
  const ok = pendientes === 0;
  const activo = grupoPendienteActivo === grupoKey ? ' is-active' : '';
  return '<button type="button" class="badge ' + (ok ? 'badge--ok' : 'badge--alert') + ' pending-group-badge' + activo + '" data-grupo="' + escapeHtml(grupoKey) + '">' +
    (ok ? '✓' : '⚠') + ' ' + pendientes + ' pendiente' + (pendientes === 1 ? '' : 's') +
    '</button>';
}

function limpiarSeleccionPendiente() {
  document.querySelectorAll('.pending-chip').forEach(btn => btn.classList.remove('is-active'));
  document.querySelectorAll('.pending-group-badge').forEach(btn => btn.classList.remove('is-active'));
  grupoPendienteActivo = null;
}
 
function aplicarFiltros() {
  const municipio = elMunicipio.value;
  const departamento = elDepartamento.value;
  const estadoInstalacion = elInstalado.value;
  const sitiosDocumentales = sitiosSegunEstadoDocumental(elDocumental.value);
  const texto = elBuscar.value.trim().toLowerCase();

  let filtradas = DATA.filter(r => {
    if (municipio && !r.municipio.toLocaleLowerCase('es').includes(municipio.toLocaleLowerCase('es'))) return false;
    if (departamento && !r.departamento.toLocaleLowerCase('es').includes(departamento.toLocaleLowerCase('es'))) return false;
    if (estadoInstalacion === 'instalado' && !r.instalado) return false;
    if (estadoInstalacion === 'no_instalado' && r.instalado) return false;
    if (sitiosDocumentales && !sitiosDocumentales.has(`${r.municipio}||${r.departamento}`)) return false;
    if (elDocumental.value === 'en_proceso' && r.estado !== 'pendiente' && r.estado !== 'sin_dato') return false;
    if (texto) {
      const hay = (r.tipo + ' ' + r.ruta + ' ' + (r.archivos || []).join(' ')).toLowerCase();
      if (!hay.includes(texto)) return false;
    }
    return true;
  });

  if (grupoPendienteActivo) {
    const [grupoMunicipio, grupoDepartamento] = grupoPendienteActivo.split('||');
    filtradas = filtradas.filter(r => {
      if (r.municipio !== grupoMunicipio) return false;
      if (r.departamento !== grupoDepartamento) return false;
      return r.estado === 'pendiente' || r.estado === 'sin_dato';
    });
  }

  const filasFiltradas = new Set(filtradas.map(r => r.fila_excel));
  const filasBase = new Set(DATA.filter(r => {
    if (municipio && !r.municipio.toLocaleLowerCase('es').includes(municipio.toLocaleLowerCase('es'))) return false;
    if (departamento && !r.departamento.toLocaleLowerCase('es').includes(departamento.toLocaleLowerCase('es'))) return false;
    if (estadoInstalacion === 'instalado' && !r.instalado) return false;
    if (estadoInstalacion === 'no_instalado' && r.instalado) return false;
    return true;
  }).map(r => r.fila_excel));
  const pendientes = [...new Map(
    filtradas
      .filter(r => r.instalado && (r.estado === 'pendiente' || r.estado === 'sin_dato'))
      .map(r => [
        `${r.municipio}||${r.departamento}`,
        {
          municipio: r.municipio,
          departamento: r.departamento,
          etiqueta: `${r.municipio} (${r.departamento})`
        }
      ])
  ).values()].sort((a, b) => a.etiqueta.localeCompare(b.etiqueta, 'es'));

  document.getElementById('resumen-municipios-pendientes').textContent = pendientes.length;
  elListadoPendientes.innerHTML = pendientes.map(item => `
    <li>
      <button
        type="button"
        class="pending-chip ${municipio === item.municipio && departamento === item.departamento ? 'is-active' : ''}"
        data-municipio="${escapeHtml(item.municipio)}"
        data-departamento="${escapeHtml(item.departamento)}"
      >${escapeHtml(item.etiqueta)}</button>
    </li>
  `).join('');
  elPanelPendientes.style.display = pendientes.length ? 'block' : 'none';

  elListadoPendientes.querySelectorAll('.pending-chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const municipioSeleccionado = btn.dataset.municipio;
      const departamentoSeleccionado = btn.dataset.departamento;
      elMunicipio.value = municipioSeleccionado;
      elDepartamento.value = departamentoSeleccionado;
      syncSelects();
      document.querySelectorAll('.pending-chip').forEach(b => b.classList.toggle('is-active', b === btn));
      aplicarFiltros();
    });
    btn.addEventListener('dblclick', evento => {
      evento.preventDefault();
      limpiarSeleccionPendiente();
      elMunicipio.value = '';
      elDepartamento.value = '';
      syncSelects();
      aplicarFiltros();
    });
  });
 
  const grupos = new Map();
  for (const r of filtradas) {
    const clave = r.municipio + '||' + r.departamento;
    if (!grupos.has(clave)) {
      grupos.set(clave, { codigo: r.codigo, municipio: r.municipio, departamento: r.departamento, fechaInstalacion: r.fecha_instalacion, rows: [] });
    }
    grupos.get(clave).rows.push(r);
  }

  let filas = '';
  for (const grupo of grupos.values()) {
    const claveGrupo = `${grupo.municipio}||${grupo.departamento}`;
    filas += `
      <tr class="group-row">
        <td colspan="3">
          <div class="group-title">
            <div class="group-code-name">
              <span class="group-codigo">${escapeHtml(grupo.codigo)}</span>
              <span class="group-municipio">${escapeHtml(grupo.municipio)}</span>
              <span class="group-departamento">${escapeHtml(grupo.departamento)}</span>
              ${grupo.fechaInstalacion ? `<span class="group-fecha">Fecha de instalación: ${escapeHtml(grupo.fechaInstalacion)}</span>` : ''}
            </div>
            ${renderBadgeGrupo(grupo.rows, claveGrupo)}
          </div>
        </td>
      </tr>`;

    for (const r of grupo.rows) {
      filas += `
        <tr>
          <td class="col-tipo">${escapeHtml(r.tipo)}</td>
          <td class="col-archivo">${renderArchivo(r)}</td>
          <td class="col-ruta">${renderRuta(r)}</td>
        </tr>`;
    }
  }
  elTbody.innerHTML = filas;

  document.querySelectorAll('.pending-group-badge').forEach(btn => {
    btn.addEventListener('click', () => {
      const grupoKey = btn.dataset.grupo;
      if (grupoPendienteActivo === grupoKey) {
        limpiarSeleccionPendiente();
      } else {
        const [grupoMunicipio, grupoDepartamento] = grupoKey.split('||');
        grupoPendienteActivo = grupoKey;
        elMunicipio.value = grupoMunicipio;
        elDepartamento.value = grupoDepartamento;
        syncSelects();
        document.querySelectorAll('.pending-group-badge').forEach(b => b.classList.toggle('is-active', b === btn));
      }
      aplicarFiltros();
    });
  });
 
  elEmpty.style.display = filtradas.length === 0 ? 'block' : 'none';
 
  elConteo.innerHTML = `Mostrando <strong>${filasFiltradas.size}</strong> de ${filasBase.size} filas`;
  scheduleStickyTableHeadUpdate();
}
 
// Mantiene las sugerencias cruzadas mientras se escribe en ambos filtros.
elDepartamento.addEventListener('input', () => {
  limpiarSeleccionPendiente();
  syncSelects();
  aplicarFiltros();
});

elMunicipio.addEventListener('input', () => {
  limpiarSeleccionPendiente();
  syncSelects();
  aplicarFiltros();
});
elInstalado.addEventListener('change', () => {
  limpiarSeleccionPendiente();
  syncSelects();
  aplicarFiltros();
});
elDocumental.addEventListener('change', () => {
  limpiarSeleccionPendiente();
  syncSelects();
  aplicarFiltros();
});
elBuscar.addEventListener('focus', abrirOpcionesTipo);
elBuscar.addEventListener('input', () => {
  limpiarSeleccionPendiente();
  aplicarFiltros();
  abrirOpcionesTipo();
});
elBuscar.addEventListener('keydown', evento => {
  if (evento.key === 'ArrowDown' || evento.key === 'ArrowUp') {
    if (elOpcionesTipo.hidden) abrirOpcionesTipo();
    const opciones = elOpcionesTipo.querySelectorAll('[role="option"]');
    if (!opciones.length) return;
    evento.preventDefault();
    const paso = evento.key === 'ArrowDown' ? 1 : -1;
    indiceTipoActivo = indiceTipoActivo < 0
      ? (paso > 0 ? 0 : opciones.length - 1)
      : (indiceTipoActivo + paso + opciones.length) % opciones.length;
    actualizarTipoActivo();
  } else if (evento.key === 'Enter' && !elOpcionesTipo.hidden && indiceTipoActivo >= 0) {
    evento.preventDefault();
    elOpcionesTipo.querySelectorAll('[role="option"]')[indiceTipoActivo].click();
  } else if (evento.key === 'Escape' && !elOpcionesTipo.hidden) {
    cerrarOpcionesTipo();
  }
});
elAlternarTipos.addEventListener('click', () => {
  if (elOpcionesTipo.hidden) {
    elBuscar.focus();
    abrirOpcionesTipo();
  } else {
    cerrarOpcionesTipo();
  }
});
document.addEventListener('click', evento => {
  if (!evento.target.closest || !evento.target.closest('.search-combobox')) {
    cerrarOpcionesTipo();
  }
});
document.getElementById('btn-reset').addEventListener('click', () => {
  limpiarSeleccionPendiente();
  elMunicipio.value = '';
  elDepartamento.value = '';
  elInstalado.value = '';
  elDocumental.value = '';
  elBuscar.value = '';
  syncSelects();
  aplicarFiltros();
});
 
aplicarFiltros();
